INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('warlords', 17251, '1980-12-31', 56, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co671u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arxtd.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warlords', 'Warlords is an arcade game released by Atari, Inc. in 1980. The game resembles a combination of Breakout and Quadrapong (an early Atari arcade game) in the sense that not only can up to 4 players play the game at the same time, but also the "forts" in the four corners of the screen are brick walls that could be broken with a flaming ball. Warlords uses spinner controllers for player control, and came in both an upright 2 player version and a 4 player cocktail version. The upright version uses a black and white monitor, and reflects the game image onto a mirror, with a backdrop of castles, giving the game a 3D feel. The upright version only supports up to two simultaneous players, which move through the levels as a team. The cocktail version is in color, and supports 1-4 players. 3-4 player games are free-for-all''s where the game ends as soon as one player wins. 1-2 player games play identical to the upright version.' FROM games WHERE igdb_id = 17251 ON CONFLICT (game_id, language_code) DO NOTHING;
