INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Man', 'Pac-Man is a 1980 maze action video game developed and released by Namco for arcades. It is considered one of the classics of the medium, virtually synonymous with video games, and an icon of 1980s popular culture. Players control Pac-Man, who must eat all the dots inside an enclosed maze while avoiding four colored ghosts. Eating large flashing dots called Power Pellets causes the ghosts to temporarily turn blue, allowing Pac-Man to eat them for bonus points.' FROM games WHERE igdb_id = 2750 ON CONFLICT (game_id, language_code) DO NOTHING;
