INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armor Attack', 'The player controls a jeep and must destroy the many tanks and helicopters that attack them in a maze-like cityscape. The jeep is armed with a rocket launcher that fires straight forward; the player can have two rockets on-screen at the time. The driving is generally similar to the well-known Combat for the Atari 2600.
