INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure', 'Adventure is a video game for the Atari 2600 video game console, released in 1980. In the game, the player controls a square avatar whose quest is to hunt an open world environment for a magical chalice, returning it to the golden castle. The game world is populated by roaming enemies: dragons, which can eat the avatar; and a bat, which randomly steals and hides items around the game world.
