INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragster', 'You have in your hand one of the most exciting video games ever designed. One word of caution: this game takes a little time to learn because it''s so challenging. It''s very tricky. So, please read these directions and give yourself some practice time. Then you can aim for the World Record.
