INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Missile Command', 'As a regional commander of three anti-missile batteries, the player must defend six cities in their zone from being destroyed. The player''s six cities are being attacked by an endless hail of ballistic missiles, some of them even splitting like multiple independently targetable reentry vehicles (MIRVs). New weapons are introduced in later levels: smart bombs that can evade a less than perfectly targeted missile, and bomber planes and satellites that fly across the screen and launch missiles of their own.' FROM games WHERE igdb_id = 12313 ON CONFLICT (game_id, language_code) DO NOTHING;
