INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King & Balloon', 'Released by Namco in the summer of 1980, King & Balloon is a shoot em up in the vein of Galaxian, but trades the outer space theme for pseudo-medieval setting. In the game, the player controls two green men who carry a cannon, as they defend the king below them from getting abducted by the balloons above, which keep invading the lower part of the screen while also shooting projectiles. Once all the balloons are shot down, the game moves on to the next level.
