INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armor Battle', 'You are on a dangerous tank mission. To reach and destroy your assigned target, you must maneuver through a field filled with enemy mines. Although these are hidden, the mine detection equipment in your tank warns you of their presence by producing a buzzing sound. This is your signal to change course on route to your target. If you should stumble into a mine, your tank will be "destroyed" and returned to its original starting position. If you get through the minefield and successfully engage the target, the built-in computer will automatically set up another challenge with a new starting position, target location, and minefield.' FROM games WHERE igdb_id = 5656 ON CONFLICT (game_id, language_code) DO NOTHING;
