INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizard of Wor', 'Wizard of Wor is an action-oriented game for one or two players. The game takes the form of several maze-like dungeons infested with monsters. The players'' characters, called Worriors, have to kill all the monsters. Player one has yellow Worriors, on the right, and player two has blue Worriors, on the left. In a two-player game, the players are also able to shoot each other''s Worriors, earning bonus points and causing the other player to lose a life. Team-oriented players can successfully advance through the game by standing back-to-back (such as in a corner) and firing at anything that comes at them.' FROM games WHERE igdb_id = 7743 ON CONFLICT (game_id, language_code) DO NOTHING;
