INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Berzerk', 'Maneuver your humanoid through the electrified mazes of robot filled rooms. You many kill off the first group of robots but initial success does not mean survival...future groups begin firing at your! Added danger lurks when Evil Otto enters. He can jump the maze walls and squash you if you linger too long!' FROM games WHERE igdb_id = 2391 ON CONFLICT (game_id, language_code) DO NOTHING;
