INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Raiders', 'Star Raiders is a first-person space combat simulator for the Atari 8-bit family of computers. It was written by Doug Neubauer, an Atari employee, and released as a cartridge by Atari in 1979. The game is considered the platform''s killer app. It was later ported to the Atari 2600, Atari 5200, and Atari ST.
