INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery House', 'In the first graphic adventure game ever, the player along with seven other people is in an old mansion hunting for some jewels. All too soon it becomes obvious that someone is killing one member of the group after another. It is the player''s task in this murder mystery to find out who the murderer is before the player is killed himself.' FROM games WHERE igdb_id = 2479 ON CONFLICT (game_id, language_code) DO NOTHING;
