INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dodge ''Em', 'Dodge ''Em is a 1980 Atari 2600 video game, a driving game based on Sega''s Head On (1979). The player controls one car and has to drive counter-clockwise, avoiding computer-controlled cars whose sole aim is to produce a head-on collision. The player''s car can travel at two speeds, a ''normal'' speed which is the same speed as computer-controlled cars, or if the player presses the controller button, his or her car travels at a ''fast'' speed double its normal speed. The computer-controlled cars have only one speed. Players change lanes by pushing the controller in the appropriate direction when their car is near one of the gaps in the roadway.' FROM games WHERE igdb_id = 17020 ON CONFLICT (game_id, language_code) DO NOTHING;
